<script setup>
import {computed,ref} from 'vue';import {t,fixed} from './i18n.js';
const props=defineProps({result:Object,mode:String,low:Number,high:Number});const selected=ref(null);
const items=computed(()=>props.mode==='thickness'?props.result.points:props.result.defects);
function color(v){const x=Math.max(0,Math.min(1,(v-props.low)/Math.max(.001,props.high-props.low)));return `hsl(${220-x*220} 65% 48%)`;}
</script>
<template><div class="wafer-map"><p>{{t('kla_points')}}</p><svg viewBox="-165 -165 330 330" role="img" :aria-label="t('kla_'+mode)"><circle r="150" fill="#f2f7f6" stroke="#557f78" stroke-width="2"/><path d="M -5 150 L 0 143 L 5 150" fill="white" stroke="#557f78"/><line x1="-147" x2="147" stroke="#d5e3df"/><line y1="-147" y2="147" stroke="#d5e3df"/><g v-for="(p,i) in items" :key="p.defectId||i"><polyline v-if="p.path" :points="p.path.map(q=>`${q.x},${-q.y}`).join(' ')" fill="none" stroke="#df7739" stroke-width="2"/><circle :cx="p.x" :cy="-p.y" :r="mode==='thickness'?8:4" :fill="mode==='thickness'?color(p.thicknessNm):'#ce663c'" @click="selected=i"><title>{{i+1}} · {{mode==='thickness'?fixed(p.thicknessNm,3)+' nm':t('kla_'+p.type)+' '+fixed(p.sizeUm,3)+' μm'}}</title></circle></g></svg><div v-if="mode==='thickness'" class="scale"><span>{{fixed(low,2)}} nm</span><i></i><span>{{fixed(high,2)}} nm</span></div><p v-else>{{t('kla_count')}}: {{items.length}}</p><label>{{t('kla_details')}}<select v-model="selected"><option :value="null">—</option><option v-for="(p,i) in items" :key="i" :value="i">{{p.defectId||i+1}} · {{mode==='thickness'?fixed(p.thicknessNm,3)+' nm':t('kla_'+p.type)}}</option></select></label><p v-if="selected!==null&&items[selected]">X {{fixed(items[selected].x,2)}} mm · Y {{fixed(items[selected].y,2)}} mm · {{mode==='thickness'?fixed(items[selected].thicknessNm,3)+' nm':fixed(items[selected].sizeUm,3)+' μm'}}</p></div></template>
<style scoped>.wafer-map{min-width:0}.wafer-map svg{display:block;width:100%;max-width:430px;margin:auto}.wafer-map p{font-size:12px;overflow-wrap:anywhere}.wafer-map select{width:100%}.scale{display:flex;align-items:center;gap:8px;font-size:12px}.scale i{flex:1;height:12px;background:linear-gradient(to right,hsl(220 65% 48%),hsl(110 65% 48%),hsl(0 65% 48%))}circle{cursor:pointer}</style>
